window.NARR = {"retime": [[3.3, 0.24], [8.9, 2.512], [12.5, 3.864], [23.4, 1.04], [28.5, 9.284], [34.45, 0.368], [35.0, 2.768], [38.3, 0.368], [42.4, 1.76]], "lines": [{"t": 0.45, "d": 3.96, "zh": "晶圓針測：探針卡一格一格地點測晶粒。", "en": "Wafer sort: a probe card testing the wafer, die by die.", "cap": true, "src": "audio/7e0968f849.mp3"}, {"t": 4.59, "d": 2.016, "zh": "把整張卡拆開。", "en": "Take the whole card apart.", "cap": true, "src": "audio/42f3cfd748.mp3"}, {"t": 6.786, "d": 5.736, "zh": "補強板、主板、MLO 載板、板背支撐，這四層是 DIS 做的。", "en": "Stiffener, main PCB, MLO substrate, backer — the four layers DIS builds.", "cap": true, "src": "audio/f5d53359ca.mp3"}, {"t": 12.702, "d": 4.368, "zh": "追一條訊號：測試機、主板、MLO 載板，", "en": "Follow one signal: tester, main PCB, MLO substrate,", "cap": true, "src": "audio/4fd79384f9.mp3"}, {"t": 17.25, "d": 2.736, "zh": "最後從探針落到晶粒上。", "en": "and finally down a probe onto the die.", "cap": true, "src": "audio/8c55eacfc4.mp3"}, {"t": 20.166, "d": 3.936, "zh": "推高步進速度，晶圓圖一下子就填滿了。", "en": "Push the index rate and the wafer map fills right in.", "cap": true, "src": "audio/3b79c2d743.mp3"}, {"t": 26.566, "d": 5.16, "zh": "剖開探針頭：兩片導板中間，夾著一排排垂直探針。", "en": "Cut the probe head open: rows of vertical probes between two guide plates.", "cap": true, "src": "audio/5f978c1f41.mp3"}, {"t": 31.906, "d": 2.112, "zh": "時間放慢十倍。", "en": "Slow time down ten times.", "cap": true, "src": "audio/591269f4b6.mp3"}, {"t": 34.198, "d": 5.064, "zh": "載台頂上來，針尖碰到鋁墊還要再壓，這叫過驅量；", "en": "The chuck rises; after touching the pad it keeps pushing — that's overdrive.", "cap": true, "src": "audio/1890a81773.mp3"}, {"t": 39.442, "d": 3.792, "zh": "探針彎曲，針尖在鋁墊上刮出針痕。", "en": "The probes bend and every tip scrubs a mark into its pad.", "cap": true, "src": "audio/0121db05ff.mp3"}, {"t": 43.414, "d": 4.296, "zh": "右邊：同樣過驅量下，懸臂針對垂直針。", "en": "On the right: cantilever vs vertical at the same overdrive.", "cap": true, "src": "audio/9c49a2c1dc.mp3"}, {"t": 47.89, "d": 3.888, "zh": "凍結時間，讓 MLO 載板翹曲一百微米。", "en": "Freeze time and warp the MLO substrate by 100 μm.", "cap": true, "src": "audio/6eeb47ded5.mp3"}, {"t": 51.958, "d": 3.888, "zh": "翹起那一側的探針碰不到晶粒，變紅了。", "en": "Probes on the high side no longer reach the die — they turn red.", "cap": true, "src": "audio/fd5022eccc.mp3"}, {"t": 56.026, "d": 2.688, "zh": "那就加大過驅量來補償⋯⋯", "en": "So crank up the overdrive to compensate…", "cap": true, "src": "audio/74a2892a5f.mp3"}, {"t": 58.894, "d": 5.88, "zh": "懸臂針刮出鋁墊、彎到回不來，垂直探針也超過降伏——壞了。", "en": "The cantilever scrubs off the pad and bends for good, the vertical probes pass yield — broken.", "cap": true, "src": "audio/7c8c43b605.mp3"}, {"t": 64.954, "d": 4.68, "zh": "下一步，我想找出它的極限，所以會做成遊戲。", "en": "Next I want to find where it breaks, so a game is coming.", "cap": false, "src": "audio/26f1579b0c.mp3"}, {"t": 69.814, "d": 4.536, "zh": "用 Claude Opus 5.5 做的，直接在瀏覽器裡就能玩。", "en": "Built with Claude Opus 5.5 — it runs live in your browser.", "cap": false, "src": "audio/67299357ef.mp3"}], "end": 75.95};
